  Lemma vec_call : forall A M model A' M' model' (STK : Z) (F : Z -> Prop) b xs nw,
    tinv A M model -> ainv MI A' M' model' -> eff MI A A' M M' (sp' - STK, sp') F -> 0 <= STK <= LIB_STACK - TOP_FRAME -> (forall x, F x -> J x) ->
    (forall x, b <= x < b + 4 * nw -> ~ F x) ->
    vec32 MI A M (sp' + 16) b xs nw ->
    (b <> 0 -> In (b, 4 * nw) (live MI A')) ->
