  Lemma st_parse : forall A M model R (q env b nw : Z) (xs : list Z),
    tinv A M model -> tregs R -> getr R 8%bv = Z_to_bv 64 q ->
    ctx_rep MI A M q env -> ~ In q (map fst (live MI A0)) ->
    vec32 MI A M (sp' + 16) b xs nw -> Zlen xs = nw -> 0 <= nw < 2 ^ 24 ->
    ((nw = 0 /\ b = 0) \/ (0 < nw /\ 0 < b /\ In (b, 4 * nw) (live MI A) /\ ~ In b (map fst (live MI A0)))) ->
