  rdn SEGS M (Z_to_bv 64 a) len = Some bs -> 0 <= k < Z.of_nat len -> 0 <= a -> a + Z.of_nat len <= 2 ^ 64 ->
  cellw SEGS M (a + k) 1 (bv_unsigned (nth (Z.to_nat k) bs (Z_to_bv 8 0))).
