  Lemma st_loop : forall (k : nat) A M model R (q b nw i : Z) (xs : list Z),
    Z.of_nat k = nw - i -> 0 <= i < nw -> 4 * nw <= n < 4 * nw + 4 ->
    tinv A M model -> tregs R -> getr R 8%bv = Z_to_bv 64 q -> getr R 9%bv = Z_to_bv 64 n -> getr R 18%bv = Z_to_bv 64 p ->
    getr R 19%bv = Z_to_bv 64 i -> getr R 21%bv = Z_to_bv 64 (2 ^ 64 - 1 - p) -> getr R 22%bv = Z_to_bv 64 (p + 1 + 4 * i) ->
    getr R 23%bv = Z_to_bv 64 (3 + 4 * i) -> getr R 24%bv = Z_to_bv 64 1 ->
    ctx_rep MI A M q RG_ENV -> ~ In q (map fst (live MI A0)) ->
    vec32 MI A M (sp' + 16) b xs nw -> Zlen xs = nw ->
    0 < b -> In (b, 4 * nw) (live MI A) -> ~ In b (map fst (live MI A0)) -> q <> b ->
    live MI A = [(b, 4 * nw)] ++ (q, CTX_SZ) :: live MI A0 ->
    rdn SEGS M (Z_to_bv 64 p) (Z.to_nat n) = Some payload -> In (p, n) (live MI A0) ->
